201	    // "{{file/<name>}}" is the path of a model a step copied under that name;
202	    // "{{attachment}}" the id of the file the person last attached;
203	    // "{{result/<pointer>}}" is the last tool result in this request;
204	    // "{{workspace/sessionId}}", "{{workspace/revision}}", "{{workspace/plateId/N}}" (the Nth plate),
205	    // "{{workspace/activePlateId}}", "{{workspace/firstObjectId}}" (the
206	    // active plate's first object), "{{workspace/filamentPreset}}" and
207	    // "{{workspace/printerPreset}}" the project now; "{{object}}" the object
208	    // an "eachObject" answer is being read for, "{{plate}}" the plate an
209	    // "eachPlate" answer is being read for.
210	    nlohmann::json prompt_fill(const nlohmann::json& value, const nlohmann::json& body, const std::string& name)
211	    {
212	        using nlohmann::json;
213	        if (value.is_object() || value.is_array()) {
214	            json filled = value;
215	            for (auto& [key, item] : filled.items())
216	                item = prompt_fill(item, body, name);
217	            return filled;
218	        }
219	        if (!value.is_string())
220	            return value;
221	        const std::string text = value;
222	        if (text.size() < 5 || text.rfind("{{", 0) != 0 || text.compare(text.size() - 2, 2, "}}") != 0)
223	            return value;
224	        const std::string path = text.substr(2, text.size() - 4);
225	        if (path == "object" && !m_prompt_object.empty())
226	            return m_prompt_object;
227	        if (path == "plate" && !m_prompt_plate.empty())
228	            return m_prompt_plate;
229	        if (path.rfind("file/", 0) == 0)
230	            return prompt_model_path(path.substr(5));
231	        if (path == "attachment" && !m_prompt_attachment.empty())
232	            return m_prompt_attachment;
233	        if (path == "workspace/sessionId")
234	            return std::to_string(installed_shell()->workspace()->snapshot().session.value());
235	        if (path == "workspace/revision")
236	            return installed_shell()->workspace()->snapshot().revision;
237	        if (path == "workspace/filamentPreset")
238	            return installed_shell()->workspace()->snapshot().setup.filament_preset;
239	        if (path == "workspace/printerPreset")
240	            return installed_shell()->workspace()->snapshot().setup.printer_preset;
241	        if (path.rfind("workspace/plateId/", 0) == 0) {
242	            const auto plates = installed_shell()->workspace()->snapshot().plates;
243	            const std::size_t number = std::stoul(path.substr(18));
244	            if (number >= 1 && number <= plates.size())
245	                return std::to_string(plates[number - 1].id.value());
246	        }
247	        if (path == "workspace/activePlateId" || path == "workspace/firstObjectId")
248	            for (const auto& plate : installed_shell()->workspace()->snapshot().plates)
249	                if (plate.active && (path == "workspace/activePlateId" || !plate.objects.empty()))
250	                    return std::to_string(path == "workspace/activePlateId" ? plate.id.value() : plate.objects.front().id.value());
251	        if (path.rfind("result/", 0) == 0) {
252	            const json& input = body.at("input");
253	            for (auto item = input.rbegin(); item != input.rend(); ++item)
254	                if (item->value("type", "") == "function_call_output") {
255	                    const json output = json::parse(item->at("output").get<std::string>());
256	                    const json::json_pointer pointer(path.substr(6));
257	                    if (output.contains("result") && output["result"].contains(pointer))
258	                        return output["result"][pointer];
259	                    break;
260	                }
261	        }
262	        check(false, name + "_fills " + text);
263	        return value;
264	    }
