266	    // Answers a held request with model output, as the service streams it.
267	    static void prompt_answer(HeldModelRequest& request, const nlohmann::json& output, const std::string& text)
268	    {
269	        using Event = Agent::AgentHttpEvent;
270	        const auto frame = [](const nlohmann::json& event) { return "event: message\ndata: " + event.dump() + "\n\n"; };
271	        if (!text.empty())
272	            request.answer(Event{Event::Kind::Data, frame({{"type", "response.output_text.delta"}, {"delta", text}}), {}, 0});
273	        request.answer(Event{Event::Kind::Data,
274	                             frame({{"type", "response.completed"}, {"response", {{"output", output}}}}), {}, 0});
275	        request.answer(Event{Event::Kind::Complete, {}, {}, 200});
276	    }
