278	    // The next request of this turn the model is asked, past any chat title.
279	    std::optional<HeldModelRequest> prompt_next_request()
280	    {
281	        for (;;) {
282	            if (!wait_for([] { return !g_held_model_requests.empty(); }, std::chrono::seconds(120)))
283	                return std::nullopt;
284	            HeldModelRequest request = std::move(g_held_model_requests.front());
285	            g_held_model_requests.pop_front();
286	            if (request.body.contains("tools"))
287	                return request;
288	            prompt_answer(request, nlohmann::json::array({{{"type", "message"}, {"role", "assistant"},
289	                                                           {"content", nlohmann::json::array({{{"type", "output_text"},
290	                                                                                               {"text", "Fixture chat"}}})}}}),
291	                          "Fixture chat");
292	        }
293	    }
