324	    // The answers' reads called after the kept request, in the same turn;
325	    // returns each with the result the app gave, as the model would read it.
326	    // A read marked "eachObject" is called once for every object on every
327	    // plate, and an "allSettings" entry with it once for every object; one
328	    // marked "eachPlate" once for every plate. A read whose result brings a
329	    // picture (view_render) keeps the result's text only.
330	    // An "allSettings" entry reads every setting of its scope:
331	    // the keys come from the app's own settings_search (an empty query lists
332	    // them all, page by page; those pages are not kept), then settings_get
333	    // reads them 32 at a time. With "keysOf" it reads, under its scope, the
334	    // keys of the scopes named, read before it, that are not its own: how
335	    // the app answers a name asked for under the wrong scope. The workspace block every result
336	    // carries is kept once, beside them, and left out of each result that
337	    // repeats it exactly.
338	    nlohmann::json prompt_answers(const std::string& name, HeldModelRequest request, const nlohmann::json& script_reads,
339	                                  std::size_t& once)
340	    {
341	        using nlohmann::json;
342	        json answers = json::array();
343	        int  calls   = 0;
344	        const json kept = request.body.at("input");
345	        once = 0;
346	        // One read in the turn; the result as the app gave it, or nothing.
347	        const auto call = [&](const std::string& tool, const json& arguments) -> std::optional<std::string> {
348	            const std::string call_id = "call_" + name + "_answer_" + std::to_string(++calls);
349	            prompt_answer(request, json::array({{{"type", "function_call"}, {"call_id", call_id}, {"name", tool},
350	                                                 {"arguments", arguments.dump()}}}), "");
351	            std::optional<HeldModelRequest> next = prompt_next_request();
352	            check(next.has_value(), name + "_answer_" + tool + "_returned");
353	            if (!next)
354	                return std::nullopt;
355	            request = std::move(*next);
356	            if (calls == 1) {
357	                // What the app sent this request only: the items of the kept
358	                // request the next one does not repeat. The runner leaves
359	                // them out when it answers a read, as the app does.
360	                const json& input = request.body.at("input");
361	                std::size_t same = 0;
362	                while (same < kept.size() && same < input.size() && kept[same] == input[same])
363	                    ++same;
364	                once = kept.size() - same;
365	                bool repeated = false;
366	                for (const json& item : input)
367	                    repeated = repeated || !prompt_skill_of(item).empty() || prompt_is_picture(item);
368	                check(!repeated, name + "_skill_and_picture_not_on_the_next_request");
369	            }
370	            // The call's own result: a picture the call returned comes after
371	            // it, as a message of its own, and is not kept.
372	            const json& sent = request.body.at("input");
373	            const auto result = std::find_if(sent.rbegin(), sent.rend(), [&call_id](const json& item) {
374	                return item.value("type", "") == "function_call_output" && item.value("call_id", "") == call_id;
375	            });
376	            check(result != sent.rend(), name + "_answer_" + tool + "_has_its_result");
377	            if (result == sent.rend())
378	                return std::nullopt;
379	            const std::string output = result->at("output");
380	            const bool succeeded = json::parse(output).value("state", "") == "succeeded";
381	            check(succeeded, name + "_answer_" + tool + "_succeeded");

